import { db } from './schema';
import type { Exercise, WorkoutPlan, WorkoutDay, UserProfile } from '@/lib/types';
import { normalizeEquipmentName } from '@/lib/utils/exerciseResolver';

// Import merged exercise data generated by scripts/merge-exercise-data.mjs
import exercisesData from '@/lib/data/merged-exercises.json';

interface ExerciseDBEntry {
  exerciseId: string;
  name: string;
  gifUrl?: string;
  targetMuscles: string[];
  bodyParts: string[];
  equipments: string[];
  secondaryMuscles: string[];
  instructions: string[];
  force?: string | null;
  level?: string;
  mechanic?: string | null;
  images?: string[];
  imageUrls?: string[];
}

export const EXERCISE_CATALOG_VERSION = 7;

export function cleanExerciseDisplayName(rawName: string): string {
  return (rawName || 'Unknown')
    .replace(/в°/g, '°')
    .replace(/\ball fours squad stretch\b/gi, 'all fours quad stretch')
    .replace(/\s*\((?:male|female)\)\s*$/i, '')
    .trim();
}

function mapRawExercise(raw: ExerciseDBEntry, fallbackIndex: number): Omit<Exercise, 'id'> {
  const exerciseId = raw.exerciseId || `ex_${fallbackIndex}`;
  const gifUrl = raw.gifUrl && raw.gifUrl.trim().length > 0
    ? raw.gifUrl.trim()
    : undefined;

  const rawEquip = (raw.equipments || [])[0] || 'body weight';

  return {
    externalId: exerciseId,
    name: cleanExerciseDisplayName(raw.name || 'Unknown'),
    force: raw.force ?? null,
    level: raw.level || 'intermediate',
    mechanic: raw.mechanic ?? null,
    equipment: normalizeEquipmentName(rawEquip),
    primaryMuscles: raw.targetMuscles || [],
    secondaryMuscles: raw.secondaryMuscles || [],
    instructions: (raw.instructions || []).map((s: string) => s.replace(/^Step:\d+\s*/i, '').replace(/в°/g, '°')),
    category: (raw.bodyParts || [])[0] || 'strength',
    images: raw.images || [],
    imageUrls: raw.imageUrls || [],
    gifUrl,
    youtubeId: undefined,
    tips: [],
    commonMistakes: [],
  };
}

function getMappedExercises(): Omit<Exercise, 'id'>[] {
  const data = exercisesData as ExerciseDBEntry[];
  return data.map((raw, index) => mapRawExercise(raw, index));
}

export async function seedDatabase(
  onProgress?: (message: string, percent: number) => void
): Promise<void> {
  onProgress?.('Initializing IronForge...', 5);

  // Seed exercises from local exercisedb data
  await seedExercises(onProgress);

  // Seed workout programs
  onProgress?.('Creating balanced workout programs...', 85);
  await ensureWorkoutPrograms();

  // Seed user profile
  onProgress?.('Setting up profile...', 95);
  const defaultProfile: Omit<UserProfile, 'id'> = {
    name: 'Athlete',
    unitSystem: 'metric',
    barWeight: 20,
    dumbbellWeight: 10,
    equipment: ['barbell', 'dumbbell', 'cable', 'body weight', 'machine', 'leverage machine'],
    defaultRestTime: 90,
    restTimerEnabled: true,
    soundEnabled: true,
    hapticEnabled: true,
    notificationsEnabled: false,
    theme: 'dark',
    isSeeded: true,
    exerciseCatalogVersion: EXERCISE_CATALOG_VERSION,
  };

  await db.userProfile.put(defaultProfile as UserProfile);
  onProgress?.('Setup complete!', 100);
}

async function seedExercises(
  onProgress?: (message: string, percent: number) => void
): Promise<void> {
  const allExercises = getMappedExercises();

  onProgress?.(`Processing ${allExercises.length} exercises...`, 15);

  onProgress?.(`Saving ${allExercises.length} exercises...`, 70);
  const chunkSize = 200;
  for (let i = 0; i < allExercises.length; i += chunkSize) {
    const chunk = allExercises.slice(i, i + chunkSize);
    await db.exercises.bulkAdd(chunk as Exercise[]);
    const pct = 70 + Math.round((i / allExercises.length) * 15);
    onProgress?.(`Saving exercises (${Math.min(i + chunkSize, allExercises.length)}/${allExercises.length})...`, pct);
  }
}

export async function migrateExerciseCatalog(
  onProgress?: (message: string, percent: number) => void
): Promise<void> {
  const mappedExercises = getMappedExercises();
  onProgress?.(`Migrating exercise catalog (${mappedExercises.length})...`, 20);

  const existingExercises = await db.exercises.toArray();
  const idByExternalId = new Map<string, number>();
  for (const exercise of existingExercises) {
    if (exercise.id && exercise.externalId) {
      idByExternalId.set(exercise.externalId, exercise.id);
    }
  }

  const upserts: Exercise[] = mappedExercises.map((exercise) => {
    const existingId = idByExternalId.get(exercise.externalId);
    return existingId ? ({ ...exercise, id: existingId } as Exercise) : (exercise as Exercise);
  });

  onProgress?.('Applying catalog updates...', 55);

  const chunkSize = 200;
  for (let i = 0; i < upserts.length; i += chunkSize) {
    const chunk = upserts.slice(i, i + chunkSize);
    await db.exercises.bulkPut(chunk);
    const pct = 55 + Math.round((i / upserts.length) * 30);
    onProgress?.(`Updating exercises (${Math.min(i + chunkSize, upserts.length)}/${upserts.length})...`, pct);
  }

  onProgress?.('Syncing balanced workout programs...', 90);
  await ensureWorkoutPrograms(true);

  const profile = await db.userProfile.toCollection().first();
  if (profile?.id) {
    const cleanedEquip = Array.isArray(profile.equipment)
      ? Array.from(new Set(profile.equipment.map((e) => normalizeEquipmentName(e))))
      : ['barbell', 'dumbbell', 'cable', 'body weight', 'machine', 'leverage machine'];
    await db.userProfile.update(profile.id, {
      exerciseCatalogVersion: EXERCISE_CATALOG_VERSION,
      equipment: cleanedEquip,
      isSeeded: true,
    });
  }

  onProgress?.('Exercise catalog & balanced plans updated!', 100);
}

